import base64
from pathlib import Path

DATA = ''''''

raw = base64.b64decode(DATA)
for directory in ('app/src/main/res/drawable-xhdpi', 'app/src/main/res/drawable-ar-xhdpi'):
    p = Path(directory)
    p.mkdir(parents=True, exist_ok=True)
    (p / 'selyro_tv_banner_asset.png').write_bytes(raw)

manifest = Path('app/src/main/AndroidManifest.xml')
text = manifest.read_text()
text = text.replace('@drawable/selyro_tv_banner', '@drawable/selyro_tv_banner_asset')
manifest.write_text(text)
print('Generated 320x180 localized TV banner assets and updated manifest')
